package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchResult struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Body  string `json:"body"`
}

// sanitizeInput removes obvious dangerous characters
func sanitizeInput(input string) string {
	// Strip null bytes and control characters
	var cleaned strings.Builder
	for _, r := range input {
		if r >= 32 && r < 127 {
			cleaned.WriteRune(r)
		}
	}
	return cleaned.String()
}

// validateCategory checks category against known values
func validateCategory(cat string) bool {
	allowed := []string{"news", "blog", "docs", "faq", "all"}
	for _, a := range allowed {
		if strings.EqualFold(a, cat) {
			return true
		}
	}
	return false
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	lang := r.URL.Query().Get("lang")

	if query == "" {
		http.Error(w, "missing query parameter", http.StatusBadRequest)
		return
	}

	query = sanitizeInput(query)

	if category != "" && !validateCategory(category) {
		http.Error(w, "invalid category", http.StatusBadRequest)
		return
	}

	// Build search query with full-text search
	baseQuery := "SELECT id, title, body FROM articles WHERE to_tsvector('english', title || ' ' || body) @@ plainto_tsquery('english', $1)"

	if category != "" && category != "all" {
		baseQuery += fmt.Sprintf(" AND category = '%s'", category)
	}

	// Language filter for multilingual content
	if lang != "" {
		lang = sanitizeInput(lang)
		baseQuery += fmt.Sprintf(" AND lang = '%s'", lang)
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Body); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
